<script setup>
import { onMounted, ref } from 'vue'

const props = defineProps({ token: { type: String, required: true }, locale: { type: String, default: 'es' } })
const copy = {
  es: { eyebrow:'Preferencias operativas',title:'Configuración',subtitle:'Organiza destinatarios y reglas de comunicación sin mezclar formularios.',refresh:'Actualizar',recipientsTab:'Correos adicionales',rulesTab:'Reglas',page:'Página',previous:'Anterior',next:'Siguiente',loading:'Cargando configuración…',addRecipient:'Agregar correo adicional',sharedOnly:'Solo para buzones compartidos que no tienen usuario en la app.',name:'Nombre',email:'Correo electrónico',copyType:'Tipo de copia',to:'Para',cc:'Copia (CC)',bcc:'Copia oculta (CCO)',saving:'Guardando…',addEmail:'Agregar correo',recipientsTitle:'Correos adicionales',sharedConfigured:'buzones compartidos configurados.',noRecipientNeeded:'No hacen falta correos adicionales para notificar a los usuarios del sistema.',active:'Activo',inactive:'Inactivo',delete:'Eliminar',newRule:'Nueva regla de correo',ruleDesc:'Define cuándo aplica y a qué correos adicionales se envía.',autoRecipients:'Los correos del cliente, el agente, el experto asignado y la administración se toman automáticamente de sus usuarios y de la solicitud.',ruleName:'Nombre de la regla',event:'Evento',serviceType:'Tipo de servicio',all:'Todos',consultationType:'Tipo de consulta',allConsultations:'Todas',source:'Origen de la solicitud',direct:'Directa desde la página',agentLink:'Enlace de agente',optionalRecipients:'Correos adicionales (opcional)',noRecipientsHint:'Agrega aquí solo correos que no pertenezcan a un usuario del sistema.',saveRule:'Guardar regla',activeRules:'Reglas activas',configured:'reglas configuradas.',noRules:'Aún no hay reglas configuradas.',allConsultationsLabel:'todas las consultas',allSources:'todos los orígenes',extraEmails:'correos adicionales',recipientCount:'destinatario(s)',recipientSaved:'Destinatario guardado correctamente.',ruleSaved:'Regla guardada correctamente.',recipientDeleted:'Destinatario eliminado.',ruleDeleted:'Regla eliminada.',confirmRecipient:'¿Eliminar el destinatario {email}?',confirmRule:'¿Eliminar la regla {name}? Esta acción no se puede deshacer.',generic:'No se pudo completar la operación.',recipientTypes:{to:'PARA',cc:'CC',bcc:'CCO'},events:{payment_approved:'Pago aprobado',payment_rejected:'Pago rechazado',request_created:'Solicitud creada',expert_assigned:'Solicitud asignada a experto',assignment_failed:'Asignación fallida',status_changed:'Cambio de estado',expert_response_submitted:'Respuesta de experto pendiente',feedback_received:'Feedback recibido',feedback_low:'Feedback con baja calificación'},services:{importacion:'Importación',exportacion:'Exportación',agente_carga:'Agente de carga'},channels:{direct_web:'Directa desde la página',agent_link:'Enlace de agente'} },
  en: { eyebrow:'Operations settings',title:'Settings',subtitle:'Organize recipients and communication rules in separate forms.',refresh:'Refresh',recipientsTab:'Additional emails',rulesTab:'Rules',page:'Page',previous:'Previous',next:'Next',loading:'Loading settings…',addRecipient:'Add additional email',sharedOnly:'For shared inboxes that do not have an app user.',name:'Name',email:'Email address',copyType:'Copy type',to:'To',cc:'CC',bcc:'BCC',saving:'Saving…',addEmail:'Add email',recipientsTitle:'Additional emails',sharedConfigured:'shared inboxes configured.',noRecipientNeeded:'No additional emails are needed to notify system users.',active:'Active',inactive:'Inactive',delete:'Delete',newRule:'New email rule',ruleDesc:'Choose when it applies and which additional addresses receive it.',autoRecipients:'Customer, agent, assigned expert, and admin emails are taken automatically from their users and the request.',ruleName:'Rule name',event:'Event',serviceType:'Service type',all:'All',consultationType:'Consultation type',allConsultations:'All',source:'Request source',direct:'Direct from website',agentLink:'Agent link',optionalRecipients:'Additional emails (optional)',noRecipientsHint:'Only add addresses here that do not belong to a system user.',saveRule:'Save rule',activeRules:'Active rules',configured:'rules configured.',noRules:'No rules configured yet.',allConsultationsLabel:'all consultations',allSources:'all sources',extraEmails:'additional emails',recipientCount:'recipient(s)',recipientSaved:'Recipient saved successfully.',ruleSaved:'Rule saved successfully.',recipientDeleted:'Recipient deleted.',ruleDeleted:'Rule deleted.',confirmRecipient:'Delete recipient {email}?',confirmRule:'Delete rule {name}? This action cannot be undone.',generic:'Could not complete the operation.',recipientTypes:{to:'TO',cc:'CC',bcc:'BCC'},events:{payment_approved:'Payment approved',payment_rejected:'Payment rejected',request_created:'Request created',expert_assigned:'Request assigned to expert',assignment_failed:'Assignment failed',status_changed:'Status changed',expert_response_submitted:'Expert response pending',feedback_received:'Feedback received',feedback_low:'Low feedback rating'},services:{importacion:'Import',exportacion:'Export',agente_carga:'Freight forwarding'},channels:{direct_web:'Direct from website',agent_link:'Agent link'} }
}
function t(key) { return copy[props.locale === 'en' ? 'en' : 'es'][key] || key }
function localizeError(message) { if (props.locale !== 'en') return message || t('generic'); const errors = { 'No se pudo completar la operación.':t('generic'),'Sesión requerida.':'Your session is required.','No tienes permisos para configurar notificaciones.':'You do not have permission to configure notifications.','La base de datos operativa no está configurada.':'The operations database is not configured.','No puedes eliminar un destinatario usado por una regla. Desactívalo desde la configuración.':'This recipient is used by a rule. Deactivate it in settings instead.','Destinatario no encontrado.':'Recipient not found.','Regla no encontrada.':'Rule not found.','Nombre y correo son obligatorios.':'Name and email are required.','Ingresa un correo válido.':'Enter a valid email address.','Tipo de destinatario inválido.':'Invalid recipient type.','Ya existe un destinatario con ese correo.':'A recipient with that email already exists.','Nombre, evento y servicio son obligatorios.':'Name, event, and service are required.','Evento inválido.':'Invalid event.','Tipo de servicio inválido.':'Invalid service type.','Origen de solicitud inválido.':'Invalid request source.','Audiencia de notificación inválida.':'Invalid notification audience.','El tipo de consulta no existe o está inactivo.':'The consultation type does not exist or is inactive.','Uno o más correos adicionales no existen o están inactivos.':'One or more additional email addresses do not exist or are inactive.','Ya existe una regla con la misma combinación de evento, servicio, consulta y origen.':'A rule already exists for this event, service, consultation, and source combination.' }; return errors[message] || t('generic') }
const tab = ref('recipients')
const loading = ref(true)
const saving = ref(false)
const error = ref('')
const notice = ref('')
const recipients = ref([])
const rules = ref([])
const consultationTypes = ref([])
const recipientPagination = ref({ page: 1, pageSize: 10, totalItems: 0, totalPages: 1 })
const rulePagination = ref({ page: 1, pageSize: 10, totalItems: 0, totalPages: 1 })
const recipient = ref({ name: '', email: '', recipientType: 'to' })
const rule = ref({ name: '', eventCode: 'payment_approved', serviceType: 'all', consultationTypeId: '', sourceChannel: '', audiences: ['configured'], recipientIds: [] })

async function request(url, options = {}) {
  const response = await fetch(url, { ...options, headers: { Authorization: `Bearer ${props.token}`, ...(options.headers || {}) } })
  const data = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(localizeError(data.error))
  return data
}

async function load() {
  loading.value = true
  error.value = ''
  try {
    const params = new URLSearchParams({ recipientPage: String(recipientPagination.value.page), rulePage: String(rulePagination.value.page) })
    const data = await request(`/api/app/settings/notifications?${params}`)
    recipients.value = data.recipients || []
    rules.value = data.rules || []
    consultationTypes.value = data.consultationTypes || []
    recipientPagination.value = data.recipientPagination || recipientPagination.value
    rulePagination.value = data.rulePagination || rulePagination.value
  } catch (loadError) { error.value = loadError.message } finally { loading.value = false }
}

async function saveRecipient() {
  saving.value = true; error.value = ''; notice.value = ''
  try { await request('/api/app/settings/notification-recipients', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(recipient.value) }); recipient.value = { name: '', email: '', recipientType: 'to' }; notice.value = t('recipientSaved'); await load() } catch (saveError) { error.value = saveError.message } finally { saving.value = false }
}

async function saveRule() {
  saving.value = true; error.value = ''; notice.value = ''
  try { await request('/api/app/settings/notification-rules', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...rule.value, audiences: ['configured'], consultationTypeId: rule.value.consultationTypeId || null, sourceChannel: rule.value.sourceChannel || null }) }); rule.value = { name: '', eventCode: 'payment_approved', serviceType: 'all', consultationTypeId: '', sourceChannel: '', audiences: ['configured'], recipientIds: [] }; notice.value = t('ruleSaved'); await load() } catch (saveError) { error.value = saveError.message } finally { saving.value = false }
}
async function removeRecipient(item) { const prompt = props.locale === 'en' ? `Delete recipient ${item.email}?` : `¿Eliminar el destinatario ${item.email}?`; if (!window.confirm(prompt)) return; try { await request(`/api/app/settings/notification-recipients/${item.id}`, { method: 'DELETE' }); notice.value = t('recipientDeleted'); await load() } catch (removeError) { error.value = removeError.message } }
async function removeRule(item) { const prompt = props.locale === 'en' ? `Delete rule ${item.name}? This action cannot be undone.` : `¿Eliminar la regla ${item.name}? Esta acción no se puede deshacer.`; if (!window.confirm(prompt)) return; try { await request(`/api/app/settings/notification-rules/${item.id}`, { method: 'DELETE' }); notice.value = t('ruleDeleted'); await load() } catch (removeError) { error.value = removeError.message } }
function changePage(kind, value) { const target = kind === 'recipients' ? recipientPagination : rulePagination; if (value < 1 || value > target.value.totalPages) return; target.value.page = value; load() }
onMounted(load)
</script>

<template>
  <section class="module-view security-view notification-config-view">
    <div class="module-heading"><div><p class="eyebrow">{{ t('eyebrow') }}</p><h1>{{ t('title') }}</h1><p>{{ t('subtitle') }}</p></div><button type="button" class="secondary-button compact" @click="load">↻ {{ t('refresh') }}</button></div>
    <div class="security-tabs"><button type="button" :class="{ active: tab === 'recipients' }" @click="tab = 'recipients'">{{ t('recipientsTab') }} <span>{{ recipientPagination.totalItems }}</span></button><button type="button" :class="{ active: tab === 'rules' }" @click="tab = 'rules'">{{ t('rulesTab') }} <span>{{ rulePagination.totalItems }}</span></button></div><div class="notification-pagination"><span>{{ t('page') }} {{ tab === 'recipients' ? recipientPagination.page : rulePagination.page }} {{ props.locale === 'en' ? 'of' : 'de' }} {{ tab === 'recipients' ? recipientPagination.totalPages : rulePagination.totalPages }}</span><div><button type="button" :disabled="(tab === 'recipients' ? recipientPagination.page : rulePagination.page) <= 1" @click="changePage(tab, (tab === 'recipients' ? recipientPagination.page : rulePagination.page) - 1)">{{ t('previous') }}</button><button type="button" :disabled="(tab === 'recipients' ? recipientPagination.page : rulePagination.page) >= (tab === 'recipients' ? recipientPagination.totalPages : rulePagination.totalPages)" @click="changePage(tab, (tab === 'recipients' ? recipientPagination.page : rulePagination.page) + 1)">{{ t('next') }}</button></div></div>
    <p v-if="notice" class="security-notice">{{ notice }}</p><p v-if="error" class="request-error">{{ error }}</p><div v-if="loading" class="module-state panel">{{ t('loading') }}</div>
    <div v-else-if="tab === 'recipients'" class="security-grid"><form class="panel security-form" @submit.prevent="saveRecipient"><div class="panel-heading"><div><h2>{{ t('addRecipient') }}</h2><p>{{ t('sharedOnly') }}</p></div><span class="metric-icon tone-blue">@</span></div><label>{{ t('name') }}<input v-model="recipient.name" type="text" :placeholder="props.locale === 'en' ? 'Operations team' : 'Equipo de operaciones'" required /></label><label>{{ t('email') }}<input v-model="recipient.email" type="email" :placeholder="props.locale === 'en' ? 'operations@company.com' : 'operaciones@empresa.com'" required /></label><label>{{ t('copyType') }}<select v-model="recipient.recipientType"><option value="to">{{ t('to') }}</option><option value="cc">{{ t('cc') }}</option><option value="bcc">{{ t('bcc') }}</option></select></label><button type="submit" class="primary-button" :disabled="saving">{{ saving ? t('saving') : t('addEmail') }} <span>→</span></button></form><article class="panel security-list"><div class="panel-heading"><div><h2>{{ t('recipientsTitle') }}</h2><p>{{ recipients.length }} {{ t('sharedConfigured') }}</p></div></div><div v-if="!recipients.length" class="empty-row">{{ t('noRecipientNeeded') }}</div><div v-for="item in recipients" :key="item.id" class="security-list-item"><div class="avatar avatar-table">@</div><div><strong>{{ item.name }}</strong><span>{{ item.email }}</span></div><div class="security-item-meta"><span class="security-status">{{ copy[props.locale === 'en' ? 'en' : 'es'].recipientTypes[item.recipientType] || item.recipientType.toUpperCase() }}</span><small>{{ item.active ? t('active') : t('inactive') }}</small><button type="button" class="danger-link" @click="removeRecipient(item)">{{ t('delete') }}</button></div></div></article></div>
    <div v-else class="notification-rules-layout"><form class="panel security-form rule-form" @submit.prevent="saveRule"><div class="panel-heading"><div><h2>{{ t('newRule') }}</h2><p>{{ t('ruleDesc') }}</p></div><span class="metric-icon tone-violet">↗</span></div><p class="notification-help">{{ t('autoRecipients') }}</p><label>{{ t('ruleName') }}<input v-model="rule.name" type="text" :placeholder="props.locale === 'en' ? 'Payment approved - Import' : 'Pago aprobado - Importación'" required /></label><label>{{ t('event') }}<select v-model="rule.eventCode"><option value="payment_approved">{{ copy[props.locale === 'en' ? 'en' : 'es'].events.payment_approved }}</option><option value="payment_rejected">{{ copy[props.locale === 'en' ? 'en' : 'es'].events.payment_rejected }}</option><option value="request_created">{{ copy[props.locale === 'en' ? 'en' : 'es'].events.request_created }}</option><option value="expert_assigned">{{ copy[props.locale === 'en' ? 'en' : 'es'].events.expert_assigned }}</option><option value="assignment_failed">{{ copy[props.locale === 'en' ? 'en' : 'es'].events.assignment_failed }}</option><option value="status_changed">{{ copy[props.locale === 'en' ? 'en' : 'es'].events.status_changed }}</option><option value="expert_response_submitted">{{ copy[props.locale === 'en' ? 'en' : 'es'].events.expert_response_submitted }}</option><option value="feedback_received">{{ copy[props.locale === 'en' ? 'en' : 'es'].events.feedback_received }}</option><option value="feedback_low">{{ copy[props.locale === 'en' ? 'en' : 'es'].events.feedback_low }}</option></select></label><label>{{ t('serviceType') }}<select v-model="rule.serviceType"><option value="all">{{ t('all') }}</option><option value="importacion">{{ copy[props.locale === 'en' ? 'en' : 'es'].services.importacion }}</option><option value="exportacion">{{ copy[props.locale === 'en' ? 'en' : 'es'].services.exportacion }}</option><option value="agente_carga">{{ copy[props.locale === 'en' ? 'en' : 'es'].services.agente_carga }}</option></select></label><label>{{ t('consultationType') }}<select v-model="rule.consultationTypeId"><option value="">{{ t('allConsultations') }}</option><option v-for="item in consultationTypes" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>{{ t('source') }}<select v-model="rule.sourceChannel"><option value="">{{ t('all') }}</option><option value="direct_web">{{ copy[props.locale === 'en' ? 'en' : 'es'].channels.direct_web }}</option><option value="agent_link">{{ copy[props.locale === 'en' ? 'en' : 'es'].channels.agent_link }}</option></select></label><fieldset class="permission-picker recipient-picker"><legend>{{ t('optionalRecipients') }}</legend><label v-for="item in recipients" :key="item.id" class="permission-option"><input v-model="rule.recipientIds" type="checkbox" :value="item.id" /><span><strong>{{ item.name }}</strong><small>{{ item.email }}</small></span></label><small v-if="!recipients.length" class="empty-inline">{{ t('noRecipientsHint') }}</small></fieldset><button type="submit" class="primary-button" :disabled="saving">{{ saving ? t('saving') : t('saveRule') }} <span>→</span></button></form><article class="panel security-list"><div class="panel-heading"><div><h2>{{ t('activeRules') }}</h2><p>{{ rules.length }} {{ t('configured') }}</p></div></div><div v-if="!rules.length" class="empty-row">{{ t('noRules') }}</div><div v-for="item in rules" :key="item.id" class="security-list-item"><div class="metric-icon tone-violet">↗</div><div><strong>{{ item.name }}</strong><span>{{ copy[props.locale === 'en' ? 'en' : 'es'].events[item.eventCode] || item.eventCode }} · {{ copy[props.locale === 'en' ? 'en' : 'es'].services[item.serviceType] || (item.serviceType === 'all' ? t('all') : item.serviceType) }} · {{ item.consultationTypeName || t('allConsultationsLabel') }} · {{ copy[props.locale === 'en' ? 'en' : 'es'].channels[item.sourceChannel] || t('allSources') }} · {{ item.recipients.length }} {{ t('extraEmails') }}</span></div><div class="security-item-meta"><span class="security-status">{{ item.active ? t('active') : t('inactive') }}</span><small>{{ item.recipients.length }} {{ t('recipientCount') }}</small><button type="button" class="danger-link" @click="removeRule(item)">{{ t('delete') }}</button></div></div></article></div>
  </section>
</template>

<style scoped>
.notification-rules-layout{display:grid;grid-template-columns:minmax(280px,.7fr) minmax(0,1.3fr);gap:16px}.notification-rules-layout .security-form{padding:20px}.notification-rules-layout .security-list{padding:20px}@media(max-width:980px){.notification-rules-layout{grid-template-columns:1fr}}
.notification-pagination{display:flex;justify-content:space-between;align-items:center;margin:12px 0;color:#98a2b3;font-size:10px}.notification-pagination>div{display:flex;gap:7px}.notification-pagination button{padding:7px 10px;border:1px solid #dce5ed;border-radius:6px;color:#526174;background:#fff;font-size:10px}.notification-pagination button:disabled{opacity:.45;cursor:not-allowed}
</style>
